function validate([n, edges, src1, src2, dest]) {
  if (!Number.isInteger(n) || n < 3 || n > 100000) return 'n is between 3 and 10^5.';
  if (!Array.isArray(edges) || edges.length > 100000) return 'edges has at most 10^5 entries.';
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 3) return 'Each edge is [from, to, weight].';
    const [from, to, weight] = edge;
    if (![from, to].every(v => Number.isInteger(v) && v >= 0 && v < n)) return 'Edge endpoints must be nodes between 0 and n - 1.';
    if (from === to) return 'An edge cannot start and end at the same node.';
    if (!Number.isInteger(weight) || weight < 1 || weight > 100000) return 'Each weight is between 1 and 10^5.';
  }
  if (![src1, src2, dest].every(v => Number.isInteger(v) && v >= 0 && v < n)) return 'src1, src2 and dest must be nodes between 0 and n - 1.';
  if (src1 === src2 || src1 === dest || src2 === dest) return 'src1, src2 and dest must be three different nodes.';
  return null;
}

