function minimumWeight(n, edges, src1, src2, dest) {
  const forward = Array.from({ length: n }, () => []);
  const backward = Array.from({ length: n }, () => []);
  for (const [from, to, weight] of edges) {
    forward[from].push([to, weight]);
    backward[to].push([from, weight]);
  }

  const push = (heap, item) => {
    heap.push(item);
    let child = heap.length - 1;
    while (child > 0) {
      const parent = (child - 1) >> 1;
      if (heap[parent][0] <= heap[child][0]) break;
      [heap[parent], heap[child]] = [heap[child], heap[parent]];
      child = parent;
    }
  };
  const pop = (heap) => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length === 0) return top;
    heap[0] = last;
    let parent = 0;
    while (true) {
      const left = 2 * parent + 1;
      const right = left + 1;
      let smallest = parent;
      if (left < heap.length && heap[left][0] < heap[smallest][0]) smallest = left;
      if (right < heap.length && heap[right][0] < heap[smallest][0]) smallest = right;
      if (smallest === parent) break;
      [heap[parent], heap[smallest]] = [heap[smallest], heap[parent]];
      parent = smallest;
    }
    return top;
  };

  const dijkstra = (graph, source) => {
    const dist = new Array(n).fill(Infinity);
    const heap = [[0, source]];
    dist[source] = 0;
    while (heap.length > 0) {
      const [distance, node] = pop(heap);
      if (distance > dist[node]) continue;
      for (const [next, weight] of graph[node]) {
        if (distance + weight < dist[next]) {
          dist[next] = distance + weight;
          push(heap, [dist[next], next]);
        }
      }
    }
    return dist;
  };

  const fromSrc1 = dijkstra(forward, src1);
  const fromSrc2 = dijkstra(forward, src2);
  const toDest = dijkstra(backward, dest);

  let best = Infinity;
  for (let meet = 0; meet < n; meet++) {
    best = Math.min(best, fromSrc1[meet] + fromSrc2[meet] + toDest[meet]);
  }
  return best === Infinity ? -1 : best;
}

