function minimumWeight(n, edges, src1, src2, dest) {
  // Try every subset of the edges and keep the lightest one in which both sources reach dest.
  const m = edges.length;
  let best = -1;
  for (let mask = 0; mask < 2 ** m; mask++) {
    let total = 0;
    const out = Array.from({ length: n }, () => []);
    for (let i = 0; i < m; i++) {
      if (Math.floor(mask / 2 ** i) % 2 === 1) {
        total += edges[i][2];
        out[edges[i][0]].push(edges[i][1]);
      }
    }
    if (best !== -1 && total >= best) continue;
    const reaches = start => {
      const seen = new Set([start]);
      const stack = [start];
      while (stack.length) {
        for (const next of out[stack.pop()]) if (!seen.has(next)) { seen.add(next); stack.push(next); }
      }
      return seen.has(dest);
    };
    if (reaches(src1) && reaches(src2)) best = total;
  }
  return best;
}

