function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  // Large graphs sometimes get a long chain through every node so that far-apart nodes connect.
  const chain = size === 'large' && rand() < 0.5;
  const n = size === 'large' ? (chain ? int(800, 1500) : int(200, 600)) : int(3, 6);
  const m = size === 'large' ? 2000 : rand() < 0.1 ? int(0, 2) : int(5, 12);
  const top = rand() < 0.3 ? 100000 : size === 'large' ? 1000 : 10;
  const edges = [];
  const addEdge = (from, to) => edges.push([from, to, int(1, top)]);
  if (chain) {
    const order = Array.from({ length: n }, (_, i) => i);
    for (let i = n - 1; i > 0; i--) {
      const j = int(0, i);
      [order[i], order[j]] = [order[j], order[i]];
    }
    for (let i = 0; i + 1 < n && edges.length < m; i++) addEdge(order[i], order[i + 1]);
  }
  while (edges.length < m) {
    const from = int(0, n - 1);
    let to = int(0, n - 2);
    if (to >= from) to++;
    addEdge(from, to);
  }
  // Three distinct special nodes.
  const src1 = int(0, n - 1);
  let src2 = int(0, n - 2);
  if (src2 >= src1) src2++;
  let dest;
  do dest = int(0, n - 1); while (dest === src1 || dest === src2);
  return [n, edges, src1, src2, dest];
}
